import Foundation

// MARK: - Sharing Faith Theme Content (20 Entries)

extension ContentLibrary {

    static let sharingFaithThemeContent: [DayContent] = [
        DayContent(
            scriptureReference: "Matthew 28:19-20",
            scriptureText: "Therefore go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit, and teaching them to obey everything I have commanded you.",
            devotionalTitle: "Go — It's a Command, Not a Suggestion",
            devotionalText: "The Great Commission starts with 'go.' It's not 'wait until you feel ready' or 'share if it comes up naturally.' Jesus commands us to go. Making disciples isn't reserved for pastors or missionaries — it's for everyone who follows Jesus. You have a commission. Go.",
            prayerText: "Lord, I hear Your command to go. I don't need to wait for a special calling — this is it. Give me the boldness and opportunity to make disciples wherever I am. I accept my commission. Send me. In Jesus' name, amen.",
            reflectionPrompt: "Have you been waiting for a special invitation to share your faith, or have you accepted the Great Commission as your own?",
            actionSteps: ["Identify one person in your life who doesn't know Jesus and pray for an opportunity to share", "Write down your commission: 'I am sent to make disciples wherever I go'"]
        ),
        DayContent(
            scriptureReference: "Romans 1:16",
            scriptureText: "For I am not ashamed of the gospel, because it is the power of God that brings salvation to everyone who believes: first to the Jew, then to the Gentile.",
            devotionalTitle: "Not Ashamed",
            devotionalText: "Paul declared he wasn't ashamed of the gospel. That implies the temptation to be ashamed was real. Sharing faith can feel embarrassing, awkward, or risky. But the gospel is the power of God for salvation. It's not your job to make it palatable — it's your job to share it. The power is in the message, not your delivery.",
            prayerText: "Lord, remove any shame I carry about the gospel. It is Your power for salvation — not something to be embarrassed about. Give me boldness to share it without apology. The message is powerful even when my delivery isn't perfect. In Jesus' name, amen.",
            reflectionPrompt: "Are there situations where you feel ashamed or hesitant to identify as a follower of Jesus?",
            actionSteps: ["Share one thing about your faith with someone today without apologizing for it", "Memorize Romans 1:16 as your declaration of boldness"]
        ),
        DayContent(
            scriptureReference: "1 Peter 3:15",
            scriptureText: "But in your hearts revere Christ as Lord. Always be prepared to give an answer to everyone who asks you to give the reason for the hope that you have. But do this with gentleness and respect.",
            devotionalTitle: "Ready With an Answer",
            devotionalText: "Peter says be prepared — not pressured. Sharing faith isn't about cornering people; it's about being ready when they ask. And they will ask, if your life shows genuine hope. Live in a way that makes people curious, then be ready to explain why you have hope. Gentleness and respect are non-negotiable in this.",
            prayerText: "Lord, help me live with such visible hope that people ask about it. And when they do, make me ready. Give me words that are gentle, respectful, and true. I want my life to provoke curiosity and my words to point to You. In Jesus' name, amen.",
            reflectionPrompt: "If someone asked you today why you have hope, what would you say?",
            actionSteps: ["Write out a 2-minute version of why you have hope in Jesus", "Practice sharing it with a believing friend so you're ready when someone asks"]
        ),
        DayContent(
            scriptureReference: "Matthew 5:13-14",
            scriptureText: "You are the salt of the earth... You are the light of the world. A town built on a hill cannot be hidden.",
            devotionalTitle: "Salt and Light",
            devotionalText: "Jesus doesn't say 'try to be salt and light.' He says you ARE salt and light. It's your identity, not your goal. Salt preserves and adds flavor. Light reveals and guides. Your presence in someone's life should make a difference — not through preaching at them, but through being who you are. You can't be hidden if you're living authentically.",
            prayerText: "Lord, I am salt and light because You made me so. Help me live my identity fully. Let my presence preserve, flavor, illuminate, and guide. I don't need to force it — I just need to be who You created me to be. In Jesus' name, amen.",
            reflectionPrompt: "In your daily environment, are you functioning as salt and light?",
            actionSteps: ["Identify one way you can be 'salt' — preserving or flavoring — in your workplace or neighborhood today", "Let your faith shine naturally in one conversation without forcing it"]
        ),
        DayContent(
            scriptureReference: "Acts 1:8",
            scriptureText: "But you will receive power when the Holy Spirit comes on you; and you will be my witnesses in Jerusalem, and in all Judea and Samaria, and to the ends of the earth.",
            devotionalTitle: "Powered by the Spirit",
            devotionalText: "Jesus didn't say 'go witness in your own strength.' He said the Holy Spirit would empower you. Sharing faith isn't about being clever, articulate, or persuasive. It's about being filled with the Spirit and telling what you've witnessed. Your story + God's Spirit = power. You don't need more training. You need more of the Spirit.",
            prayerText: "Holy Spirit, fill me with power to be a witness. I can't do this in my own strength or with my own words. Empower me. Give me courage, wisdom, and the right words at the right time. I am Your witness — in my city, my community, and wherever You send me. In Jesus' name, amen.",
            reflectionPrompt: "Are you trying to share faith in your own strength, or are you relying on the Holy Spirit's power?",
            actionSteps: ["Before any faith-sharing opportunity, pray 'Holy Spirit, speak through me'", "Ask the Spirit to show you one person who needs to hear about Jesus today"]
        ),
        DayContent(
            scriptureReference: "2 Corinthians 5:20",
            scriptureText: "We are therefore Christ's ambassadors, as though God were making his appeal through us. We implore you on Christ's behalf: Be reconciled to God.",
            devotionalTitle: "You Are an Ambassador",
            devotionalText: "An ambassador represents their home country in a foreign land. You are Christ's ambassador — representing heaven wherever you go. Ambassadors don't freelance; they deliver their king's message. Your job isn't to share your opinions about God. It's to deliver God's appeal: be reconciled to Him. You represent the King.",
            prayerText: "Lord, I am Your ambassador. Help me represent You well wherever I go. Give me Your message, Your heart, and Your urgency. I don't speak for myself — I speak on behalf of the King. Use me to appeal to others: be reconciled to God. In Jesus' name, amen.",
            reflectionPrompt: "If people judged God's character by watching you, what would they conclude?",
            actionSteps: ["Act as Christ's ambassador in every interaction today — represent Him well", "Deliver God's message of reconciliation to one person through a kind act or conversation"]
        ),
        DayContent(
            scriptureReference: "Mark 5:19",
            scriptureText: "Jesus did not let him, but said, 'Go home to your own people and tell them how much the Lord has done for you, and how he has had mercy on you.'",
            devotionalTitle: "Start With Your Story",
            devotionalText: "The healed man wanted to follow Jesus. Instead, Jesus sent him home to share his story. Your personal testimony is your most powerful tool. Nobody can argue with what God has done in your life. You don't need a theology degree. You need your story. What has the Lord done for you? Start there.",
            prayerText: "Lord, help me tell my story well. What You've done in my life is undeniable evidence of Your love. Give me courage to share it and words to make it clear. My testimony is powerful because it's true. Use my story to draw others to You. In Jesus' name, amen.",
            reflectionPrompt: "Can you tell your faith story in 3 minutes? What would you include?",
            actionSteps: ["Write your faith story in three parts: before Jesus, meeting Jesus, after Jesus", "Share your story with one person today — even just a piece of it"]
        ),
        DayContent(
            scriptureReference: "Colossians 4:5-6",
            scriptureText: "Be wise in the way you act toward outsiders; make the most of every opportunity. Let your conversation be always full of grace, seasoned with salt, so that you may know how to answer everyone.",
            devotionalTitle: "Graceful Conversations",
            devotionalText: "Paul's advice for sharing faith is remarkably practical: be wise, seize opportunities, and let your words be full of grace. Not arguments. Not debates. Grace. Seasoned with salt — interesting, flavorful, making people want more. The goal isn't winning arguments. It's having conversations so gracious that people are drawn to the God behind your words.",
            prayerText: "Lord, make my conversations full of grace and seasoned with salt. Help me be wise with outsiders and alert to every opportunity. I want my words to draw people in, not push them away. Give me gracious, interesting, life-giving words today. In Jesus' name, amen.",
            reflectionPrompt: "Are your conversations about faith full of grace or full of debate?",
            actionSteps: ["In your next conversation with a non-believer, focus entirely on grace — no arguments", "Look for one opportunity today to steer a conversation gently toward faith"]
        ),
        DayContent(
            scriptureReference: "John 4:35",
            scriptureText: "Don't you have a saying, 'It's still four months until harvest'? I tell you, open your eyes and look at the fields! They are ripe for harvest.",
            devotionalTitle: "Open Your Eyes",
            devotionalText: "The disciples thought the harvest was far off. Jesus said it was ready now. We often think people aren't ready to hear about God. But Jesus sees readiness we miss. The fields around you are ripe — coworkers, neighbors, family members, friends who are searching even if they don't show it. Open your eyes. Someone near you is ready.",
            prayerText: "Lord, open my eyes to see the harvest around me. Help me stop assuming people aren't ready and start looking for the ones who are. Show me who is searching, who is hurting, who is open. The fields are ripe — give me eyes to see and courage to reach out. In Jesus' name, amen.",
            reflectionPrompt: "Who in your life might be more ready to hear about Jesus than you think?",
            actionSteps: ["Pray by name for three people in your life who don't know Jesus", "Ask God to show you one person today who is 'ripe for harvest'"]
        ),
        DayContent(
            scriptureReference: "Romans 10:14-15",
            scriptureText: "How, then, can they call on the one they have not believed in? And how can they believe in the one of whom they have not heard? And how can they hear without someone preaching to them? And how can anyone preach unless they are sent?",
            devotionalTitle: "Someone Has to Tell Them",
            devotionalText: "Paul traces the chain: salvation requires belief, belief requires hearing, hearing requires someone to tell them. If you don't share, who will? The person next to you may never hear about Jesus unless you open your mouth. You are the link in the chain. Don't break it by staying silent.",
            prayerText: "Lord, I am the link in someone's chain of salvation. Help me not break it through silence or fear. Someone needs to hear, and You've placed me in their path. Give me the words and the courage. I accept my role in their story. In Jesus' name, amen.",
            reflectionPrompt: "Who might never hear about Jesus if you don't tell them?",
            actionSteps: ["Identify one person who might not hear about Jesus without you and take a step toward sharing", "Pray: 'Lord, who have You placed in my path specifically so they can hear?'"]
        ),
        DayContent(
            scriptureReference: "1 Corinthians 3:6-7",
            scriptureText: "I planted the seed, Apollos watered it, but God has been making it grow. So neither the one who plants nor the one who waters is anything, but only God, who makes things grow.",
            devotionalTitle: "You Plant, God Grows",
            devotionalText: "You're not responsible for converting anyone. That's God's job. Your job is to plant seeds and water them. Sometimes you plant and someone else waters. Sometimes you water what someone else planted. The growth is always God's work. This takes the pressure off. Share faithfully and trust God with the results.",
            prayerText: "Lord, I'll plant and water. You make things grow. Take the pressure off me to produce results. My job is faithfulness, not conversion. Help me plant seeds generously and water them lovingly, trusting that You'll do what only You can do. In Jesus' name, amen.",
            reflectionPrompt: "Have you been putting too much pressure on yourself to 'convert' people instead of simply planting seeds?",
            actionSteps: ["Plant one seed today — a kind word, a shared verse, an invitation — without worrying about the outcome", "Thank God for someone who planted a seed in your life that eventually led to faith"]
        ),
        DayContent(
            scriptureReference: "2 Timothy 4:2",
            scriptureText: "Preach the word; be prepared in season and out of season; correct, rebuke and encourage — with great patience and careful instruction.",
            devotionalTitle: "In Season and Out",
            devotionalText: "Paul tells Timothy to be ready to share whether it's convenient or not. 'In season' is when opportunities come naturally. 'Out of season' is when you have to create them. Both require preparation. You never know when a conversation will turn spiritual. Stay ready. The best opportunities often come when you least expect them.",
            prayerText: "Lord, keep me ready — in season and out of season. Whether the moment is convenient or unexpected, help me be prepared to share Your truth. Give me patience, wisdom, and the right words for every situation. I stay ready because You stay faithful. In Jesus' name, amen.",
            reflectionPrompt: "Are you only willing to share faith when it's convenient, or are you ready out of season too?",
            actionSteps: ["Prepare a brief testimony that you could share at a moment's notice", "Look for an 'out of season' opportunity to share faith today"]
        ),
        DayContent(
            scriptureReference: "Matthew 9:36-38",
            scriptureText: "When he saw the crowds, he had compassion on them, because they were harassed and helpless, like sheep without a shepherd. Then he said to his disciples, 'The harvest is plentiful but the workers are few. Ask the Lord of the harvest, therefore, to send out workers into his harvest field.'",
            devotionalTitle: "Compassion Drives Sharing",
            devotionalText: "Jesus didn't share faith because He had to. He shared because He had compassion. He saw harassed, helpless people and His heart broke. Sharing faith starts with compassion, not obligation. When you truly see people the way Jesus sees them — lost, hurting, searching — sharing becomes natural because you care too much to stay silent.",
            prayerText: "Lord, give me Your eyes for people. Help me see them as You see them — harassed, helpless, in need of a shepherd. Let compassion, not obligation, drive my sharing. Break my heart for what breaks Yours. And send me as a worker into Your harvest. In Jesus' name, amen.",
            reflectionPrompt: "Do you share faith out of compassion or obligation? How might compassion change your approach?",
            actionSteps: ["Ask God to give you His compassion for one specific person today", "Pray Matthew 9:38 — ask the Lord to send workers, including you"]
        ),
        DayContent(
            scriptureReference: "Philemon 1:6",
            scriptureText: "I pray that your partnership in the faith may be effective, so that you will have a full understanding of every good thing we share for the sake of Christ.",
            devotionalTitle: "Sharing Deepens Understanding",
            devotionalText: "Paul reveals something surprising: sharing your faith makes YOUR faith more effective. When you articulate what you believe, you understand it better. Teaching solidifies learning. Sharing isn't just for the listener's benefit — it deepens your own understanding of every good thing you have in Christ. The more you share, the more you grow.",
            prayerText: "Lord, make my sharing of faith effective. As I tell others about You, deepen my own understanding. Help me discover new dimensions of Your goodness through the act of sharing it. I want to grow as I help others grow. In Jesus' name, amen.",
            reflectionPrompt: "When was the last time sharing your faith taught you something new about God?",
            actionSteps: ["Share one aspect of your faith with someone today and notice what you learn in the process", "Journal about how sharing has deepened your own understanding of God"]
        ),
        DayContent(
            scriptureReference: "Isaiah 52:7",
            scriptureText: "How beautiful on the mountains are the feet of those who bring good news, who proclaim peace, who bring good tidings, who proclaim salvation, who say to Zion, 'Your God reigns!'",
            devotionalTitle: "Beautiful Feet",
            devotionalText: "God calls the feet of gospel-sharers beautiful. Not their eloquence, their education, or their technique — their feet. The willingness to go is what God celebrates. You don't need to be polished. You just need to show up with good news. Your willing feet are beautiful to God.",
            prayerText: "Lord, make my feet beautiful by making them willing. I want to go where You send me with good news. I don't need to be perfect — I just need to show up. Use my willing feet to carry Your peace, Your salvation, and Your reign to someone who needs it. In Jesus' name, amen.",
            reflectionPrompt: "Are your feet going toward people who need good news, or staying in comfortable places?",
            actionSteps: ["Go to one person today with a word of encouragement or good news about God", "Pray: 'Lord, where do You want my feet to carry Your gospel today?'"]
        ),
        DayContent(
            scriptureReference: "John 9:25",
            scriptureText: "He replied, 'Whether he is a sinner or not, I don't know. One thing I do know. I was blind but now I see!'",
            devotionalTitle: "You Don't Need All the Answers",
            devotionalText: "The healed blind man couldn't answer the Pharisees' theological questions. But he could say one thing with absolute certainty: 'I was blind but now I see.' You don't need to be a theologian to share faith. You need to know what God has done for you. If He's changed your life, that's your message. Let the theologians debate. You just tell what you know.",
            prayerText: "Lord, I may not have all the answers, but I know what You've done for me. Give me confidence in my story. I was lost, but now I'm found. I was blind, but now I see. Help me share what I know with boldness and simplicity. In Jesus' name, amen.",
            reflectionPrompt: "What is the one thing you know for certain that God has done in your life?",
            actionSteps: ["Craft your 'one thing I know' statement about what God has done for you", "Share it with someone today — keep it simple and personal"]
        ),
        DayContent(
            scriptureReference: "2 Corinthians 4:7",
            scriptureText: "But we have this treasure in jars of clay to show that this all-surpassing power is from God and not from us.",
            devotionalTitle: "Imperfect Vessels, Perfect Message",
            devotionalText: "God chose to put His treasure — the gospel — in clay jars. Ordinary, fragile, imperfect you. Why? So everyone knows the power is God's, not yours. Your imperfections don't disqualify you from sharing faith. They actually make the message more powerful. When broken people share about a healing God, the contrast points to Him.",
            prayerText: "Lord, I'm a clay jar — cracked, ordinary, fragile. But You've put Your treasure in me. Use my imperfections to showcase Your power. I don't need to be perfect to share a perfect message. Let my brokenness point to Your wholeness. In Jesus' name, amen.",
            reflectionPrompt: "Have your imperfections stopped you from sharing faith? How does this verse change that?",
            actionSteps: ["Share honestly about a struggle AND how God has met you in it — vulnerability is powerful", "Stop waiting to be 'good enough' to share and share from where you are today"]
        ),
        DayContent(
            scriptureReference: "Proverbs 11:30",
            scriptureText: "The fruit of the righteous is a tree of life, and the one who is wise wins souls.",
            devotionalTitle: "Wisdom Wins People",
            devotionalText: "Soul-winning isn't about aggressive tactics — it's about wisdom. A righteous life bears fruit that draws people in like a tree of life. People are attracted to genuine goodness, authentic faith, and wise living. The best evangelism is often a life so compelling that people ask what's different about you. Live wisely. Win souls. They're connected.",
            prayerText: "Lord, make my life a tree of life that draws others to You. Give me wisdom to win souls — not through pressure, but through a life that's genuinely attractive because of Your presence in it. Let my fruit speak louder than my words. In Jesus' name, amen.",
            reflectionPrompt: "Is your life attractive enough to make people curious about your faith?",
            actionSteps: ["Focus on bearing good fruit today through kindness, integrity, and joy", "Ask God to make your life so compelling that someone asks what's different about you"]
        ),
        DayContent(
            scriptureReference: "Luke 15:7",
            scriptureText: "I tell you that in the same way there will be more rejoicing in heaven over one sinner who repents than over ninety-nine righteous persons who do not need to repent.",
            devotionalTitle: "Heaven Throws a Party",
            devotionalText: "When one person comes to faith, heaven celebrates. One. Not a stadium full. Not a viral video. One person repenting causes a party in heaven. That means your one conversation, your one invitation, your one act of courage in sharing could trigger a heavenly celebration. Every person matters to God that much.",
            prayerText: "Lord, help me remember that every person I share with matters enough to throw a party over. Give me the urgency of heaven's joy. One soul is worth everything. Use me to bring one more person into Your family today. Let heaven celebrate because I was willing. In Jesus' name, amen.",
            reflectionPrompt: "Does the thought of heaven celebrating over one person change how you view sharing your faith?",
            actionSteps: ["Pray for one specific person's salvation today with the urgency of heaven's joy", "Take one step toward sharing faith with that person this week"]
        ),
        DayContent(
            scriptureReference: "Matthew 10:19-20",
            scriptureText: "But when they arrest you, do not worry about what to say or how to say it. At that time you will be given what to say, for it will not be you speaking, but the Spirit of your Father speaking through you.",
            devotionalTitle: "Don't Worry About the Words",
            devotionalText: "Jesus promises that when the moment comes, the Spirit will give you the words. Your biggest fear about sharing faith — not knowing what to say — is addressed directly by Jesus. The Spirit of God will speak through you. Your job is to show up and open your mouth. God's job is to fill it with the right words.",
            prayerText: "Lord, I release my fear of not knowing what to say. Your Spirit will give me the words when the time comes. I show up, I open my mouth, and You fill it. Take away my performance anxiety about sharing faith. It's Your Spirit speaking through me, and that's enough. In Jesus' name, amen.",
            reflectionPrompt: "Has fear of saying the wrong thing kept you silent? What would change if you trusted the Spirit to give you words?",
            actionSteps: ["The next time you have an opportunity to share, trust the Spirit and speak without overthinking", "Pray each morning: 'Holy Spirit, give me words for whoever needs them today'"]
        ),
    ]
}
